SELECT *
FROM `Shipping incidents`
WHERE `Name` LIKE '%British%' AND (`Cargo` LIKE '%wheat%' OR `Cargo` LIKE '%gas oil%');

SELECT *
FROM `Astronaut_EVA`
WHERE `Astronaut` LIKE '%Williams%' OR `Astronaut` LIKE '%Solovyev%';

SELECT `Player`, `Points Per Game`
FROM `NBA_2000_season_stats`
WHERE `Player` LIKE 'L%';

SELECT *
FROM `Sports Competitions Spectatorship`
WHERE `Competition` LIKE '%League%';

SELECT *
FROM `TV_episode_statistics`
WHERE `Airdate` LIKE '%November%' AND `BBC Three weekly ranking` IS NOT NULL;

SELECT *
FROM `MusicAlbum`
WHERE `Title` LIKE '%Lady%' OR `Lyrics` LIKE '%ICP%';

SELECT *
FROM `Tennis tournaments outcomes`
WHERE `Opponent in the final` LIKE 'J%';

SELECT *
FROM `Subframe_Page_Name_Word_Bits`
WHERE `Name` LIKE '%LSB%' OR `Name` LIKE 'D%';
